                    let timestamp = data.bufferInfo.timeStamp;//时间戳
                    let frameNum = data.bufferInfo.frameNum;//视频的帧号，音频没有帧号
                    let bitrate = data.bufferInfo.bitrate;//音频码率，视频没有码率信息
        
                    //2、申请传入transform.wasm中的视频buffer
